-\frac{1}{(s+1)^{2}} & \frac{s}{(s+1)^{2}}
\end{array}\right]\left[\begin{array}{l}
0 \\
1
\end{array}\right]+1 \\ 
&=\left[\begin{array}{ll}
3 & -2
\end{array}\right]\left[\begin{array}{c}
\frac{1}{(s+1)^{2}} \\
\frac{s}{(s+1)^{2}}
\end{array}\right]+1 \\
&=\frac{3}{(s+1)^{2}}-\frac{2 s}{(s+1)}+1 \\
&=\frac{3-2 s+s^{2}+2 s+1}{s^{2}+2 s+1} \\
&=\frac{s^{2}+4}{s^{2}+2 s+1}
